# Relabel pr-2 -> P2 and remove pr-3 label

gmail_token = globals().get('gmail_token')
if not gmail_token:
    raise RuntimeError('Missing gmail_token')

# Ensure we have current pr2_ids and pr3_ids; if not, fetch them
page_limit = 20
api_map = {
    'inbox': apis.gmail.show_inbox_threads,
    'outbox': apis.gmail.show_outbox_threads,
    'archived': apis.gmail.show_archived_threads,
    'spam': apis.gmail.show_spam_threads,
    'snoozed': apis.gmail.show_snoozed_threads,
    'starred': apis.gmail.show_starred_threads,
}

def fetch_label_ids(label_name):
    all_ids = set()
    for api_fn in api_map.values():
        page_index = 0
        while True:
            res = api_fn(access_token=gmail_token, label=label_name, page_index=page_index, page_limit=page_limit)
            if not res:
                break
            for item in res:
                all_ids.add(int(item['email_thread_id']))
            page_index += 1
    return all_ids

pr2_ids = globals().get('pr2_ids')
pr3_ids = globals().get('pr3_ids')
if pr2_ids is None:
    pr2_ids = fetch_label_ids('pr-2')
if pr3_ids is None:
    pr3_ids = fetch_label_ids('pr-3')

print('to_change_counts', {'pr2': len(pr2_ids), 'pr3': len(pr3_ids)})

# Relabel pr-2 threads
relabel_results = {'P2_set':0, 'errors':0}
for thread_id in sorted(pr2_ids):
    try:
        apis.gmail.label_thread(email_thread_id=thread_id, label='P2', access_token=gmail_token)
        relabel_results['P2_set'] += 1
    except Exception as e:
        relabel_results['errors'] += 1
        print('label_thread_error_pr2', thread_id, str(e)[:200])

print('relabel_results', relabel_results)

# Remove pr-3 label
unlabel_results = {'pr3_removed':0, 'errors':0}
for thread_id in sorted(pr3_ids):
    try:
        apis.gmail.unlabel_thread(email_thread_id=thread_id, access_token=gmail_token)
        unlabel_results['pr3_removed'] += 1
    except Exception as e:
        unlabel_results['errors'] += 1
        print('unlabel_thread_error_pr3', thread_id, str(e)[:200])

print('unlabel_results', unlabel_results)

