labels = ['pr-1','pr-2','pr-3','P1','P2']
current_sets = {lbl: fetch_label_ids(lbl) for lbl in labels}
counts = {lbl: len(s) for lbl, s in current_sets.items()}
print('final_counts', counts)
print('overlaps', {
